package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Fraction_hashCode_TriageGen0Test {

    @Test
    public void testHashCode_SimpleFraction() {
        // Fraction(1, 2) -> numerator=1, denominator=2
        // Expected: 37 * (37 * 17 + 1) + 2 = 37 * (629 + 1) + 2 = 37 * 630 + 2 = 23310 + 2 = 23312
        Fraction fraction = new Fraction(1, 2);
        int expectedHashCode = 37 * (37 * 17 + fraction.getNumerator()) + fraction.getDenominator();
        assertEquals(expectedHashCode, fraction.hashCode());
    }

    @Test
    public void testHashCode_ZeroNumerator() {
        // Fraction(0, 5) -> numerator=0, denominator=5
        // Expected: 37 * (37 * 17 + 0) + 5 = 37 * 629 + 5 = 23273 + 5 = 23278
        Fraction fraction = new Fraction(0, 5);
        int expectedHashCode = 37 * (37 * 17 + 0) + 5;
        assertEquals(expectedHashCode, fraction.hashCode());
    }

    @Test
    public void testHashCode_NegativeNumerator() {
        // Fraction(-1, 2) -> numerator=-1, denominator=2
        // Expected: 37 * (37 * 17 - 1) + 2 = 37 * 628 + 2 = 23236 + 2 = 23238
        Fraction fraction = new Fraction(-1, 2);
        int expectedHashCode = 37 * (37 * 17 + (-1)) + 2;
        assertEquals(expectedHashCode, fraction.hashCode());
    }

    @Test
    public void testHashCode_NegativeDenominator() {
        // Note: Fraction internal implementation usually normalizes signs, 
        // but we test based on the formula provided.
        // If constructor normalizes to numerator=-1, den=2, we test that.
        Fraction fraction = new Fraction(1, -2); 
        // Assuming normalization to (-1, 2)
        int expectedHashCode = 37 * (37 * 17 + fraction.getNumerator()) + fraction.getDenominator();
        assertEquals(expectedHashCode, fraction.hashCode());
    }

    @Test
    public void testHashCode_LargeValues() {
        // Testing with larger integers to check for integer overflow behavior consistency
        Fraction fraction = new Fraction(Integer.MAX_VALUE / 100, Integer.MAX_VALUE / 100);
        int expectedHashCode = 37 * (37 * 17 + fraction.getNumerator()) + fraction.getDenominator();
        assertEquals(expectedHashCode, fraction.hashCode());
    }

    @Test
    public void testHashCode_ConsistencyWithEquals() {
        // hashCode should be consistent for equal objects
        Fraction f1 = new Fraction(1, 3);
        Fraction f2 = new Fraction(2, 6); // Should reduce to 1/3

        assertEquals(f1, f2);
        assertEquals(f1.hashCode(), f2.hashCode());
    }

    @Test
    public void testHashCode_FromDouble() {
        // Testing path via double constructor
        Fraction fraction = new Fraction(0.5); // 1/2
        int expectedHashCode = 37 * (37 * 17 + 1) + 2;
        assertEquals(expectedHashCode, fraction.hashCode());
    }
}
